import{_ as s,o as n,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"90. 练习：可移植多线程程序","description":"The Little Book of C 中文版 — 90. 练习：可移植多线程程序","frontmatter":{"title":"90. 练习：可移植多线程程序","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","09-可移植与现代 C","中文"],"description":"The Little Book of C 中文版 — 90. 练习：可移植多线程程序","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":"90","sidebarWeight":"90","alternateZh":"/posts/c教程/zh-CN/09-可移植与现代 C/090-Practice Portable Multithreaded Program","alternateEn":"/posts/c教程/en-US/09-Portable and Modern C/090-Practice Portable Multithreaded Program"},"headers":[],"relativePath":"posts/c教程/zh-CN/09-可移植与现代 C/090-Practice Portable Multithreaded Program.md","filePath":"posts/c教程/zh-CN/09-可移植与现代 C/090-Practice Portable Multithreaded Program.md","lastUpdated":1790163617000}'),l={name:"posts/c教程/zh-CN/09-可移植与现代 C/090-Practice Portable Multithreaded Program.md"};function t(i,a,o,c,d,r){return n(),e("div",null,[...a[0]||(a[0]=[p(`<p>[English version](/posts/c教程/en-US/09-Portable and Modern C/090-Practice Portable Multithreaded Program)</p><h4 id="跟练交付物" tabindex="-1">跟练交付物 <a class="header-anchor" href="#跟练交付物" aria-label="Permalink to &quot;跟练交付物&quot;">​</a></h4><ul><li>已具备状态：完成第 081-089 课，能重新编译上一章示例。</li><li>工作目录：<code>~/c-course-labs/090-portable-threads</code>。</li><li>第一条命令：macOS / Linux 运行 <code>mkdir -p ~/c-course-labs/090-portable-threads &amp;&amp; cd ~/c-course-labs/090-portable-threads</code>；Windows PowerShell 运行 <code>New-Item -ItemType Directory -Force &quot;$HOME\\c-course-labs\\090-portable-threads&quot;; Set-Location &quot;$HOME\\c-course-labs\\090-portable-threads&quot;</code>。</li><li>成功证据：保留源码、可执行文件、<code>evidence.md</code>，并记录编译命令、线程运行输出、平台或编译器差异说明。</li><li>本章边界：本章关注平台差异和并发正确性；Windows 移植可以作为对照记录，不影响主线完成。</li><li>重置方式：删除本章生成的可执行文件、临时数据和输出文件，保留源码与 <code>evidence.md</code> 方便复盘。</li></ul><p>是时候将您学到的所有内容（内存管理、线程、同步和可移植性）整合到一个有凝聚力的程序中了。</p><p>在第 9 章的最后一节中，您将构建一个可移植的多线程计数器，它可以跨架构、编译器和系统正确运行，从而在实践中展示干净、安全和现代的 C。</p><h4 id="步骤-1-目标" tabindex="-1">步骤 1. 目标 <a class="header-anchor" href="#步骤-1-目标" aria-label="Permalink to &quot;步骤 1. 目标&quot;">​</a></h4><p>我们将编写一个程序：</p><ul><li>使用生成多个线程<code>pthread</code>（POSIX 标准）。</li><li>使用原子操作进行安全并发更新。</li><li>无论 CPU 或字节顺序如何，都打印一致的结果。</li><li>在 Linux、macOS 和 Windows 上干净地编译（通过 MinGW）。</li><li>使用现代、可读的 C11–C23 风格。</li></ul><h4 id="步骤-2-规划设计" tabindex="-1">步骤 2. 规划设计 <a class="header-anchor" href="#步骤-2-规划设计" aria-label="Permalink to &quot;步骤 2. 规划设计&quot;">​</a></h4><ol><li>共享柜台：<code>atomic_int</code>用于线程安全的增量。</li><li>线程功能：每个线程执行一个增量循环。</li><li>计时：测量经过的时间以了解性能。</li><li>便携性：使用<code>#ifdef</code>以实现跨平台兼容性。</li><li>最终验证：确保结果等于总增量。</li></ol><h4 id="步骤-3-完整的小代码" tabindex="-1">步骤 3. 完整的小代码 <a class="header-anchor" href="#步骤-3-完整的小代码" aria-label="Permalink to &quot;步骤 3. 完整的小代码&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;stdatomic.h&gt;</span></span>
<span class="line"><span>#include &lt;pthread.h&gt;</span></span>
<span class="line"><span>#include &lt;stdint.h&gt;</span></span>
<span class="line"><span>#include &lt;time.h&gt;</span></span>
<span class="line"><span>#ifdef _WIN32</span></span>
<span class="line"><span>#include &lt;windows.h&gt;</span></span>
<span class="line"><span>#define SLEEP(ms) Sleep(ms)</span></span>
<span class="line"><span>#else</span></span>
<span class="line"><span>#include &lt;unistd.h&gt;</span></span>
<span class="line"><span>#define SLEEP(ms) usleep((ms) * 1000)</span></span>
<span class="line"><span>#endif</span></span>
<span class="line"><span>#define THREADS 4</span></span>
<span class="line"><span>#define ITERATIONS 250000</span></span>
<span class="line"><span>atomic_int counter = 0;</span></span>
<span class="line"><span>void* worker(void* arg) {</span></span>
<span class="line"><span>    int id = *(int*)arg;</span></span>
<span class="line"><span>    for (int i = 0; i &lt; ITERATIONS; i++) {</span></span>
<span class="line"><span>        atomic_fetch_add(&amp;counter, 1);</span></span>
<span class="line"><span>        if (i % 100000 == 0 &amp;&amp; id == 0)</span></span>
<span class="line"><span>            SLEEP(1);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    return NULL;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>double now(void) {</span></span>
<span class="line"><span>    struct timespec ts;</span></span>
<span class="line"><span>    clock_gettime(CLOCK_MONOTONIC, &amp;ts);</span></span>
<span class="line"><span>    return ts.tv_sec + ts.tv_nsec / 1e9;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    pthread_t threads[THREADS];</span></span>
<span class="line"><span>    int ids[THREADS];</span></span>
<span class="line"><span>    double start = now();</span></span>
<span class="line"><span>    for (int i = 0; i &lt; THREADS; i++) {</span></span>
<span class="line"><span>        ids[i] = i;</span></span>
<span class="line"><span>        if (pthread_create(&amp;threads[i], NULL, worker, &amp;ids[i]) != 0) {</span></span>
<span class="line"><span>            perror(&quot;pthread_create failed&quot;);</span></span>
<span class="line"><span>            return 1;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    for (int i = 0; i &lt; THREADS; i++)</span></span>
<span class="line"><span>        pthread_join(threads[i], NULL);</span></span>
<span class="line"><span>    double end = now();</span></span>
<span class="line"><span>    printf(&quot;Counter = %d (expected %d)\\n&quot;, counter, THREADS * ITERATIONS);</span></span>
<span class="line"><span>    printf(&quot;Elapsed time: %.3f seconds\\n&quot;, end - start);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="步骤-4-工作原理" tabindex="-1">步骤 4. 工作原理 <a class="header-anchor" href="#步骤-4-工作原理" aria-label="Permalink to &quot;步骤 4. 工作原理&quot;">​</a></h4><p>原子计数器：<code>atomic_fetch_add</code>确保增量是原子的且无竞争的，无需使用互斥体。</p><p>线程创建：每个线程运行<code>worker()</code>独立运作。</p><p>同步：<code>pthread_join</code>确保所有线程在打印结果之前完成。</p><p>时间：使用<code>clock_gettime()</code>用于精确的跨平台计时。</p><p>睡眠宏：<code>SLEEP(ms)</code>抽象化了 Windows 和 POSIX 之间的平台差异。</p><h4 id="步骤5-编译并运行" tabindex="-1">步骤5.编译并运行 <a class="header-anchor" href="#步骤5-编译并运行" aria-label="Permalink to &quot;步骤5.编译并运行&quot;">​</a></h4><p>在 Linux 或 macOS 上：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -std=c23 -pthread -O2 -Wall -Wextra portable_threads.c -o portable_threads</span></span>
<span class="line"><span>./portable_threads</span></span></code></pre></div><p>在 Windows 上（MinGW）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -std=c23 -O2 -Wall -Wextra portable_threads.c -o portable_threads.exe -lws2_32</span></span>
<span class="line"><span>portable_threads.exe</span></span></code></pre></div><p>预期输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Counter = 1000000 (expected 1000000)</span></span>
<span class="line"><span>Elapsed time: 0.134 seconds</span></span></code></pre></div><p>该程序以完美的准确性完成，没有竞争条件，并且可以跨平台运行。</p><h4 id="步骤-6-提高可移植性" tabindex="-1">步骤 6. 提高可移植性 <a class="header-anchor" href="#步骤-6-提高可移植性" aria-label="Permalink to &quot;步骤 6. 提高可移植性&quot;">​</a></h4><p>用 C11 替换 pthreads<code>&lt;threads.h&gt;</code>如果您想要仅标准 C：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;threads.h&gt;</span></span></code></pre></div><p>使用<code>thrd_create</code>和<code>thrd_join</code>而不是<code>pthread_create</code>和<code>pthread_join</code>.</p><p>使用静态断言进行验证：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>_Static_assert(THREADS &gt; 0, &quot;Must have at least one thread&quot;);</span></span></code></pre></div><p>使用条件宏来解决系统差异（<code>_WIN32</code>,<code>__linux__</code>,<code>__APPLE__</code>).</p><h4 id="步骤-7-安全性和清晰度检查表" tabindex="-1">步骤 7. 安全性和清晰度检查表 <a class="header-anchor" href="#步骤-7-安全性和清晰度检查表" aria-label="Permalink to &quot;步骤 7. 安全性和清晰度检查表&quot;">​</a></h4><p>✅ 没有不安全地共享原始指针 ✅ 原子操作防止竞争 ✅ 睡眠和计时是跨平台的 ✅ 干净、现代的语法，支持 C23 ✅ 易于修改（例如，更改线程数或工作负载）</p><h4 id="第-8-步-为什么它是便携式的" tabindex="-1">第 8 步：为什么它是便携式的 <a class="header-anchor" href="#第-8-步-为什么它是便携式的" aria-label="Permalink to &quot;第 8 步：为什么它是便携式的&quot;">​</a></h4><ul><li>仅使用标准 C 和 POSIX API。</li><li>避免依赖于字节序或未定义的行为。</li><li>对特定于平台的代码有清晰的抽象。</li><li>依赖于原子类型，而不是特定于 CPU 的内在函数。</li><li>无需更改即可在 x86、ARM、RISC-V 和其他处理器上运行。</li></ul><h4 id="第-9-步-为什么它很重要" tabindex="-1">第 9 步：为什么它很重要 <a class="header-anchor" href="#第-9-步-为什么它很重要" aria-label="Permalink to &quot;第 9 步：为什么它很重要&quot;">​</a></h4><p>这个小程序体现了 C 最擅长的：</p><ul><li>速度：线程性能接近硬件。</li><li>控制：显式内存和并发性。</li><li>清晰度：现代 C 语法使其具有可读性。</li><li>可移植性：可以在任何有编译器的地方运行。</li></ul><p>这就是当今的 C，简约、精确且可靠。</p><h4 id="第-10-步-亲自尝试一下" tabindex="-1">第 10 步：亲自尝试一下 <a class="header-anchor" href="#第-10-步-亲自尝试一下" aria-label="Permalink to &quot;第 10 步：亲自尝试一下&quot;">​</a></h4><ol><li>改变<code>THREADS</code>并观察性能扩展。 2.用互斥体替换原子计数器，比较速度。</li><li>将其移植到 Windows 并验证输出。</li><li>添加计时来测量每个线程的持续时间。</li><li>使用 C11 进行实验<code>&lt;threads.h&gt;</code>纯标准 C 的 API。</li></ol><p>您已经完成了第 9 章“可移植和现代 C”。接下来是第 10 章：构建真实项目，您将应用这些基础知识来构建真实世界的系统、库、服务器和解释器，所有这些都使用干净、惯用的 C 语言。</p>`,44)])])}const b=s(l,[["render",t]]);export{u as __pageData,b as default};
